import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long v = next();
            // One doubling per bit after the leading one, one +1 per set bit.
            int ops = v == 0 ? 0 : (63 - Long.numberOfLeadingZeros(v)) + Long.bitCount(v);
            out.append(ops).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"math/bits"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		v := uint64(next())
		// One doubling per bit after the leading one, one +1 per set bit.
		ops := 0
		if v != 0 {
			ops = bits.Len64(v) - 1 + bits.OnesCount64(v)
		}
		w.WriteString(strconv.Itoa(ops) + "\n")
	}
}
